        "node -e \"process.exit(0)\""
      ]
    },
    {
      "id": "10_requirements",
      "name": "Requirements confirmation",
      "prompt": "prompts/codexflow/10_requirements.md",
      "checks": [
        "node --test tests/default-docs.test.cjs tests/invocation-target.test.cjs"
      ]
    },
    {
      "id": "20_design",
      "name": "Design and architecture",
      "prompt": "prompts/codexflow/20_design.md",
      "checks": [
        "node --test tests/work-items.test.cjs tests/markdown-webview.test.cjs"
      ]
    },
    {
      "id": "30_implementation",
      "name": "Implementation",
      "prompt": "prompts/codexflow/30_implementation.md",
      "checks": [
        "node --test tests/*.test.cjs"
      ]
    },
    {
      "id": "40_test_refactor",
      "name": "Test and refactor",
      "prompt": "prompts/codexflow/40_test_refactor.md",
      "checks": [
        "node --test tests/*.test.cjs"
      ]
    },
    {
      "id": "50_release_check",
      "name": "Release check",
      "prompt": "prompts/codexflow/50_release_check.md",
      "checks": [
        "npm run platform:gate",
        "npm run release:check"
      ]
    }
  ]
}

